import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"大過","description":"焦氏易林注 - 大過","frontmatter":{"title":"大過","description":"焦氏易林注 - 大過"},"headers":[],"relativePath":"zh/classics/jiaoyilin/028.md","filePath":"zh/classics/jiaoyilin/028.md"}'),l={name:"zh/classics/jiaoyilin/028.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="大過" tabindex="-1">大過 <a class="header-anchor" href="#大過" aria-label="Permalink to “大過”">​</a></h1><h3 id="大過-1" tabindex="-1">大過 <a class="header-anchor" href="#大過-1" aria-label="Permalink to “大過”">​</a></h3><h3 id="大過之乾" tabindex="-1">大過之乾 <a class="header-anchor" href="#大過之乾" aria-label="Permalink to “大過之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>日在北陸，陰蔽陽目。萬物空虛，不見長育。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此用《大過》象。乾為日、為寒，故曰日在北陸。大過本末陰，故曰陰蔽陽目。伏坤為萬物、為空虛，坤死故不長。</p><h3 id="大過之坤" tabindex="-1">大過之坤 <a class="header-anchor" href="#大過之坤" aria-label="Permalink to “大過之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>鬼泣哭社，悲商無後。甲子昧爽，殷人絕祀。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>坤為鬼、為社，《大過》兌為哭泣，坤為傷、為悲。伏震為子，位東故曰甲子。震為晨，兌為昧，故曰昧爽。震為子，殷，子姓。坤殺故曰絕祀。○商，從宋元本，汲古作&quot;鬼傷哭社&quot;。按《墨子非攻篇》：&quot;至商王紂，婦妖宵出，有鬼宵吟&quot;，又《論衡》雲&quot;紂之時，夜郊鬼哭&quot;，又雲&quot;紂郊鬼哭&quot;，惟《虞初志》亡，不能得其詳耳。</p><h3 id="大過之屯" tabindex="-1">大過之屯 <a class="header-anchor" href="#大過之屯" aria-label="Permalink to “大過之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>涉塗履危，不利有為。安坐垂裳，乃無災殃。門戶自開，君憂不昌。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>震為塗、為涉、為履，坎為危，故涉塗履危，險在前，故不利有為，艮止故宜安坐。坤為裳、為災殃。安坐垂裳，高拱無為，故無災殃。坤為門戶，震為君，坎為憂。○裳，汲古作堂，依宋元本。</p><h3 id="大過之蒙" tabindex="-1">大過之蒙 <a class="header-anchor" href="#大過之蒙" aria-label="Permalink to “大過之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>陽失其紀，枯木復起。秋華冬實，君不得息。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>上陽在上，二陽陷陰中皆不當位，故曰失紀。震為木、為起，坤虛故曰枯木。震為華，艮為實，伏兌為秋，坎為冬，故曰秋華冬實。震為君。○秋華冬實，宋元本作秋葉冬華，依汲古。息，汲古作失，依宋元本。</p><h3 id="大過之需" tabindex="-1">大過之需 <a class="header-anchor" href="#大過之需" aria-label="Permalink to “大過之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>大樹之子，百條共母。當夏六月，枝葉盛茂。鸞鳳以庇，召伯避暑。翩翩偃仰，各得其所。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>此用《大過》象。巽為大樹，伏震為子，故曰大樹之子。巽為條、為母，乾為百，故曰百條共母。兌為月，乾數六，故曰六月。伏坤為文、為鸞鳳，巽為枝葉，乾為盛茂，鸞鳳居枝葉之中，故曰鸞鳳以庇。伏震為召伯，坤為暑，一陽潛坤下，故曰避暑。正反震故曰翩翩偃仰。用遇卦象兼及遇卦伏象，《易林》象學之難窺如此。○鳳，宋元本作鳥，翩作偏，各作甚，均依汲古。</p><h3 id="大過之訟" tabindex="-1">大過之訟 <a class="header-anchor" href="#大過之訟" aria-label="Permalink to “大過之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>秉鉞執殳，挑戰先驅。不從元帥，敗破為憂。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>《詩》：&quot;伯也執殳，為王前驅&quot;，《左傳》：邲之戰，晉軍不用命，遂敗，言先榖不從元師荀林父命而挑戰也。離為戈兵，故曰鉞殳。伏震為戰、為驅，坎為破敗、為憂。○從，汲古訛役，依宋元本。</p><h3 id="大過之師" tabindex="-1">大過之師 <a class="header-anchor" href="#大過之師" aria-label="Permalink to “大過之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>啟室開關，巡狩釋冤。夏台羑里，湯文悅喜。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>坎為室，震為啟、為開，坤為關，故曰啟戶開關。震為巡狩、為釋，坎為冤，坤為台、為里，夏離故曰夏台，震大塗故曰羑里。羑，亦道路也。震為王，坤為文，故曰湯文。震為喜。○巡狩，宋元本作逃得，非。羑作牖，均依汲古。</p><h3 id="大過之比" tabindex="-1">大過之比 <a class="header-anchor" href="#大過之比" aria-label="Permalink to “大過之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>衰來無成，淵溺在傾。狗吠夜驚，家乃不寧。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>坤死故衰滅，坤為淵，坎陷故曰溺傾。艮為狗，伏兌為吠，坤為夜，故曰狗吠夜驚。艮為家，坎險故不寧。○成，汲古作幾，傾作頃，狗吠作吠狗，均依宋元本。</p><h3 id="大過之小畜" tabindex="-1">大過之小畜 <a class="header-anchor" href="#大過之小畜" aria-label="Permalink to “大過之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>西鄰少女，未有所許。志如委衣，不出房戶。心無所得，傅母何咎。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>兌為西、為少女，伏坎為志，坤為衣裳，坤柔故曰委衣。未有所許，謂未字人也。志如委衣，言柔順也。艮為戶房，艮止故不出。坎為心，坤為母。全用伏象。</p><h3 id="大過之履" tabindex="-1">大過之履 <a class="header-anchor" href="#大過之履" aria-label="Permalink to “大過之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>狗吠夜驚，履鬼頭頸。危者弗傾，患者不成。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>伏《謙》。艮為狗，震為吠、為驚，坎為夜、為鬼，震在坎上，故曰履鬼頭頸。坎為大首，故曰頭也。坎為危患，震解，故危患皆免也。○患者，宋元本作患滅，依汲古。</p><h3 id="大過之泰" tabindex="-1">大過之泰 <a class="header-anchor" href="#大過之泰" aria-label="Permalink to “大過之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>當年少寡，獨與孤處。雞鳴犬吠，無敢難者。我生不辰，獨嬰寒苦。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>通《否》。乾為年，巽為寡，艮少故曰少寡。坤亦為寡，故曰獨與孤處。巽為雞，艮為犬，震為鳴吠、為辰、為生，坤喪，故曰不辰。乾為寒，坤為獨。</p><h3 id="大過之否" tabindex="-1">大過之否 <a class="header-anchor" href="#大過之否" aria-label="Permalink to “大過之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>無道之君，鬼哭其門。命與下國，絕不得食。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>乾為君，坤惡，故曰無道。坤為鬼、為門，艮為哭。巽為命，坤為國。兌口為食，兌覆故不得食。《論衡》：&quot;紂之時鬼泣哭社&quot;。</p><h3 id="大過之同人" tabindex="-1">大過之同人 <a class="header-anchor" href="#大過之同人" aria-label="Permalink to “大過之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>乘龍南游，夜過糟邱，脫厄無憂。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>伏《師》。震為龍、為南游、為糟、為陵，故為邱。坤為夜，坎為厄，震出故脫厄。</p><h3 id="大過之大有" tabindex="-1">大過之大有 <a class="header-anchor" href="#大過之大有" aria-label="Permalink to “大過之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>馬躓車傷，長舌破家。東關二五，晉君出走。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>事詳《頤》之《臨》。</p><h3 id="大過之謙" tabindex="-1">大過之謙 <a class="header-anchor" href="#大過之謙" aria-label="Permalink to “大過之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>瓜葩瓠實，百女同室。⺶苦不熟，未有妃合。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>艮為果蓏，故曰瓜、曰瓠。震為葩，艮為實、為室，坤為百、為女，故曰百女同室。坎為⺶、為合。妃，匹也。⺶苦不熟，言或酸或苦，尚未成熟，故未有所遇，猶室女之未有妃合也。○妃，汲古作配，依宋元本。</p><h3 id="大過之豫" tabindex="-1">大過之豫 <a class="header-anchor" href="#大過之豫" aria-label="Permalink to “大過之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>晨風文翰，大舉就溫。昧過我邑，羿無所得。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為晨，坤為風晨。風，隼也。艮為隼，震為翰，坤文，曰文翰。《逸周書王會篇》：&quot;蜀人以文翰，文翰若皋雞&quot;，而《說文》翰下引《逸周書》曰&quot;大翰若翬雉，一名風，然則晨風、文翰為一物，不有《說文》焉知《易林》以晨風與文翰連文之故哉。坎為昧，坤為邑、為惡，故曰羿。坤喪故無得。《詩秦風》：&quot;鴥彼晨風，鬱彼北林&quot;，鬱，《齊詩》蓋作溫，詳《小畜》之《革》。○昧，汲古作時，依宋元本。按：《說文》作大翰，大為文之訛。</p><h3 id="大過之隨" tabindex="-1">大過之隨 <a class="header-anchor" href="#大過之隨" aria-label="Permalink to “大過之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>瀺瀺浞浞，塗泥至轂。馬濘不進，虎嚙我足。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>兌澤，互大坎故曰瀺浞。瀺，水聲。浞，濡也。坎為轂、為泥濘，震為馬，艮止故不進。艮為虎，兌口為嚙，震為足。○浞，依元本，汲古作促。</p><h3 id="大過之蠱" tabindex="-1">大過之蠱 <a class="header-anchor" href="#大過之蠱" aria-label="Permalink to “大過之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>膠車駕東，與雨相逢。五楘解墮，頓輈獨坐，憂為身禍。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>震為車、為東，兌為雨，故曰膠車、故曰與雨相逢，言膠車遇水即解，故五楘解墮也。《詩秦風》：&quot;五楘梁輈&quot;，《毛傳》：&quot;五，五束也，楘，厯錄也，言以皮五處束輈上，其文厯錄章美也。&quot;巽數五，故曰五楘。巽隕落故曰解墮，艮止故曰頓、曰坐。○五楘解墮，宋元本作故革懈惰，汲古作放革懈惰。頓輈，宋元本作頓輪，汲古作頓禹為身，各本皆作不為，均依《遯》之《益》校改。</p><h3 id="大過之臨" tabindex="-1">大過之臨 <a class="header-anchor" href="#大過之臨" aria-label="Permalink to “大過之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>六家作權，公室剖分。陰制其陽，唐叔失明。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>晉六卿擅權剖分公室，唐叔，晉始封之君。伏乾數六，艮為家、為室，震為公，兌折故剖分。臨陰多陽少，陽又在下，故為陰制。艮為叔、為明，艮伏故失明，言失其明祀也。</p><h3 id="大過之觀" tabindex="-1">大過之觀 <a class="header-anchor" href="#大過之觀" aria-label="Permalink to “大過之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>去室離家，來奔大都。火息復明，姬伯以昌，商人失功。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>艮為室家，風散故曰去。離坤為大都，伏震故曰來奔大都。艮為火、為明，伏震為姬、為伯、為昌、為商人。</p><h3 id="大過之噬嗑" tabindex="-1">大過之噬嗑 <a class="header-anchor" href="#大過之噬嗑" aria-label="Permalink to “大過之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>牧羊稻園，聞虎喧歡。危懼喘息，終無禍患。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《節》。</p><h3 id="大過之賁" tabindex="-1">大過之賁 <a class="header-anchor" href="#大過之賁" aria-label="Permalink to “大過之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>嬰兒求乳，母歸其子，黃麑悅喜。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>詳《無妄》之《節》。○汲古多&quot;乃得甘飽&quot;四字，依宋元本刪。兒，宋元本作孩，依汲古。</p><h3 id="大過之剝" tabindex="-1">大過之剝 <a class="header-anchor" href="#大過之剝" aria-label="Permalink to “大過之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>廓落失業，跨禍度福，利無所得。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>坤虛故曰廓落，坤喪故失業。</p><h3 id="大過之復" tabindex="-1">大過之復 <a class="header-anchor" href="#大過之復" aria-label="Permalink to “大過之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>出入無時，憂患為災。行人失牛，利去不來。老馬遺駒，勿與久居。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>冬至震出，夏至巽入，震巽相往來，故曰出入無時。坤為災、為憂患、為牛、為失，震為行人，故曰行人失牛。巽為利，巽伏，故曰利去不來。坤為馬、為老，震子為騎，坤上震不，故曰遺駒。震出故不居。○無，元本作不，從宋本、汲古。患，宋元本作禍，遺作少，均依汲古。老，汲古訛若，依宋元本。</p><h3 id="大過之無妄" tabindex="-1">大過之無妄 <a class="header-anchor" href="#大過之無妄" aria-label="Permalink to “大過之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>風怒漂木，女惑生疾。陽失其服，陰孽為賊。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>巽風，震巽皆為木，故曰漂木。巽為女、為進退、為疾病，故曰女惑生疾。《左傳昭元年》：&quot;女，陽物而晦時，淫則生內熱惑蠱之疾&quot;。乾為陽，卦二至上遯陰銷陽，故曰陽失其服。服，職也。巽為賊。○木，宋元本作水，依汲古。惑，汲古作感，服作時，依宋元本。</p><h3 id="大過之大畜" tabindex="-1">大過之大畜 <a class="header-anchor" href="#大過之大畜" aria-label="Permalink to “大過之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>車馬病傷，不利越鄉。幽人元亨，去晦就明。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>震為車馬，兌毀故傷。艮為鄉，艮止故不利。艮為幽人，兌鄉晦，艮在上故曰元亨、故曰去晦就明。○病，汲古作疾，元亨作無貪，均依宋元本。</p><h3 id="大過之頤" tabindex="-1">大過之頤 <a class="header-anchor" href="#大過之頤" aria-label="Permalink to “大過之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>三奇六耦，各有所主。周南召南，聖人所在。德義流行，民悅以喜。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>震數三，伏乾數六，乾奇坤耦，震為主，言陰陽各有所主也。震為周、為召、為南，故曰周南召南。伏乾為聖人，坤為民，震悅喜。</p><h3 id="大過之大過" tabindex="-1">大過之大過 <a class="header-anchor" href="#大過之大過" aria-label="Permalink to “大過之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>典冊法書，藏在蘭台。雖遭亂潰，獨不遇災。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《大畜》。○在，元本作閣，依汲古。</p><h3 id="大過之坎" tabindex="-1">大過之坎 <a class="header-anchor" href="#大過之坎" aria-label="Permalink to “大過之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>坐爭立訟，紛紛訩訩。卒成禍亂，災及家公。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>中爻正反艮震故曰爭訟。艮坐震立，艮家震公，坎為禍災。○訩訩，宋元本作忽忽，非，依汲古。</p><h3 id="大過之離" tabindex="-1">大過之離 <a class="header-anchor" href="#大過之離" aria-label="Permalink to “大過之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>凶憂為殘，使我不安。從之南國，以除心疾。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>兌折故曰心殘、曰不安。離為南，伏艮為國，震為從、為之，言從往南國也。坎為心、為疾，坎伏故曰除。</p><h3 id="大過之咸" tabindex="-1">大過之咸 <a class="header-anchor" href="#大過之咸" aria-label="Permalink to “大過之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>愛我嬰女，牽衣不與。冀幸高貴，反得賤下。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《未濟》。○第二句各本皆作牽引不得，第四句宋元本作反得不興，汲古作反目下賤，均依《屯》之《未濟》校。</p><h3 id="大過之恒" tabindex="-1">大過之恒 <a class="header-anchor" href="#大過之恒" aria-label="Permalink to “大過之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>宜行賈市，所聚必倍。載喜抱子，與利為友。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>巽為賈市、為近市利三倍。上震為喜、為子、為車，故曰載喜，伏艮手故曰抱子。巽為利，震巽同聲，又互兌故曰友。○聚，汲古作取，依宋元本。友，宋元本作市，依汲古。</p><h3 id="大過之遯" tabindex="-1">大過之遯 <a class="header-anchor" href="#大過之遯" aria-label="Permalink to “大過之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>坐席未溫，憂來扣門。逾牆北走，兵交我後，脫於虎口。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>艮為坐、為火，風散故未溫。巽為憂，乾為門，艮手故曰扣門。艮為牆、為兵戈、為虎，伏震為逾、為走、為脫、為後，兌為口。</p><h3 id="大過之大壯" tabindex="-1">大過之大壯 <a class="header-anchor" href="#大過之大壯" aria-label="Permalink to “大過之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>赤帝懸車，廢職不朝。叔帶之災，居於泛廬。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>乾為赤、為帝，震為車，伏巽為系，車在上故曰懸車。伏艮為叔，巽為帶，艮為廬。泛，水名，《左傳僖三［當作二］十四年》：&quot;天王出居於鄭，來告難，曰：不榖得罪於母之寵子帶，鄙在鄭地泛。&quot;首二句義未詳。</p><h3 id="大過之晉" tabindex="-1">大過之晉 <a class="header-anchor" href="#大過之晉" aria-label="Permalink to “大過之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>子畏於匡，厄困陳蔡。明德不危，竟自免害。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《鼎》。○免，宋元本作克，依汲古。</p><h3 id="大過之明夷" tabindex="-1">大過之明夷 <a class="header-anchor" href="#大過之明夷" aria-label="Permalink to “大過之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>逐雁南飛，馬牛疾罷。不見漁池，失利憂危。牢戶之冤，脫免無患。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為雁、為南、為飛，故曰逐雁南飛。震為馬，坤為牛，震健坤柔，故馬疾牛罷。坎為池，坤為漁，坎隱故不見。坤為戶，坎為獄，故曰牢戶。坎為憂患，震出故脫免無患。</p><h3 id="大過之家人" tabindex="-1">大過之家人 <a class="header-anchor" href="#大過之家人" aria-label="Permalink to “大過之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>推輦上山，高仰重難。終日至暮，不見阜顛。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>此用《大過》伏象。坤為輦，艮為推、為山、為高、為終、為日、為阜顛，坤為暮也。</p><h3 id="大過之睽" tabindex="-1">大過之睽 <a class="header-anchor" href="#大過之睽" aria-label="Permalink to “大過之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>憂不為患，福在堂門，使吾偃安。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>坎為憂患，兌悅故不患。伏艮為門堂、為安、為吾。</p><h3 id="大過之蹇" tabindex="-1">大過之蹇 <a class="header-anchor" href="#大過之蹇" aria-label="Permalink to “大過之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>春桃生華，季女宜家。受福多年，男為邦君。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《坤》。</p><h3 id="大過之解" tabindex="-1">大過之解 <a class="header-anchor" href="#大過之解" aria-label="Permalink to “大過之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>高山之顛，去地億千。雖有兵寇，足以自守。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>地，元本作俗，依汲古。此仍用《大過》對象頤。頤上艮為高山、為顛，坤為地、為億千、為師旅，故為兵寇。艮為守。</p><h3 id="大過之損" tabindex="-1">大過之損 <a class="header-anchor" href="#大過之損" aria-label="Permalink to “大過之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>過時厯月，役夫顦顇。處子嘆室，思我伯叔。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>艮時兌月，故日過時厯月。震夫坤役兌折，故役夫顦顇。兌為處子、為口，故為嘆息。《東山》詩，婦嘆於室是也。艮為室、為叔，震為伯，坤為我、為思，故曰思我伯叔。</p><h3 id="大過之益" tabindex="-1">大過之益 <a class="header-anchor" href="#大過之益" aria-label="Permalink to “大過之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>太微復明，說升傅岩，乃稱高宗。艮為星、為明，故曰太微復明。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>艮為岩，震為說，又為主，故曰高宗。《史記》：&quot;殷武丁求得傅說於傳險中，殷道復興&quot;，《晉書天文志》：&quot;太微，天子庭也，五帝之坐也&quot;，喻殷道復興。○元本下有&quot;疾在頭頸，和不能生，滅其令名&quot;三句，與上文義戾，宋本無，汲古作一作云云，以三句為另一林辭尚可，均依宋本刪。</p><h3 id="大過之夬" tabindex="-1">大過之夬 <a class="header-anchor" href="#大過之夬" aria-label="Permalink to “大過之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>旁多小星，三五在東。早夜晨興，勞苦無功。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>通《剝》。艮為星，艮少故曰小星。《詩召南》、《毛傳》雲：&quot;三心星，五噣星&quot;，噣即柳也。以下用《大過》象，大過伏震為早、為晨，坤為夜、為勞苦。</p><h3 id="大過之姤" tabindex="-1">大過之姤 <a class="header-anchor" href="#大過之姤" aria-label="Permalink to “大過之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>東鄉煩煩，相與笑言。子般鞭犖，圉人作患。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。震為東、為笑言。巽為鞭，坤牛故曰鞭犖。犖，駁牛也。坤為圉，震為人，故曰圉人。《周禮夏官》：&quot;圉人掌牧馬芻秣之事&quot;。坤為患，《左傳莊三十二年》：&quot;雩講於梁氏女，公子觀之圉人犖自牆外與之戲，子般怒，使鞭之，後圉人犖賊子般於黨氏&quot;。○犖，汲古訛革，依宋元本。</p><h3 id="大過之萃" tabindex="-1">大過之萃 <a class="header-anchor" href="#大過之萃" aria-label="Permalink to “大過之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>鼻移在頭，枯葦復生。下朽上榮，家乃不寧，其舍不成。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>艮為鼻，又為頭，在一處故曰鼻移在頭。伏震為葦、為生，巽下斷故曰下朽。兌為華，在上故曰上榮。艮為家舍，巽隕故不寧、不成。</p><h3 id="大過之升" tabindex="-1">大過之升 <a class="header-anchor" href="#大過之升" aria-label="Permalink to “大過之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>蝦蟆群聚，從天請雨。雲雷集聚，應時輒與，得其願所。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>巽為蝦蟆，坤為群聚。伏乾為天，兌為雨，坤為雲，震為雷。元本註雲：《續漢書禮儀志》：&quot;春旱求雨，取蝦蟆置社中&quot;。○與，宋元本作下，依汲古。願所，汲古作所願，依宋元本。</p><h3 id="大過之困" tabindex="-1">大過之困 <a class="header-anchor" href="#大過之困" aria-label="Permalink to “大過之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>大步上車，南到喜家。送我貂裘，與福載來。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>伏震故曰步、曰車、曰南、曰喜。艮為家、為貂，震為裘、為福。全用伏象。</p><h3 id="大過之井" tabindex="-1">大過之井 <a class="header-anchor" href="#大過之井" aria-label="Permalink to “大過之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>賊仁傷德，天怒不福。斬刈宗社，失其土宇。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>通《噬嗑》。坎為賊、震為仁、為怒、為福，坎破故不福。艮為天、為宗社、為土宇。艮為刀兵，故曰斬刈。○上宇，宋元本作宇守，依汲古。</p><h3 id="大過之革" tabindex="-1">大過之革 <a class="header-anchor" href="#大過之革" aria-label="Permalink to “大過之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>從蝟見虎，雖危不殆，終已無咎。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>《史記龜策傳》註：&quot;蝟能伏虎&quot;，故不危殆。乾為虎，伏坎為蝟、為危殆。○無咎，汲古作不處，從宋元本。殆，音以。</p><h3 id="大過之鼎" tabindex="-1">大過之鼎 <a class="header-anchor" href="#大過之鼎" aria-label="Permalink to “大過之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>履素行德，卒蒙佑福。與堯佑食，君子有息。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。震為履、為白，故曰履素。震為福佑、為帝，故曰堯。兌為口，故曰食。艮為君子。○素行，汲古作行素，依宋元本。</p><h3 id="大過之震" tabindex="-1">大過之震 <a class="header-anchor" href="#大過之震" aria-label="Permalink to “大過之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>利在北陸，寒苦難得。憂危之患，福為道門。商叔生存。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>坎為北陸、為寒，震生於子，故曰利在北陸。坎為危，震為福，艮為道、為門、為叔。震為商、為生，故曰商叔生存。</p><h3 id="大過之艮" tabindex="-1">大過之艮 <a class="header-anchor" href="#大過之艮" aria-label="Permalink to “大過之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>四蹇六盲，足痛難行。終日至暮，不離其鄉。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>坎為蹇，震卦數四，故曰四蹇。互大離為盲，坎數六，故曰六盲。震為足、為行，坎痛故難行。艮為終日、為鄉，坎為暮，坎陷艮止，故不離其鄉。○鄉，與行韻，依宋元本，汲古作鄰。按：震為鄰，三至上正反震，故曰不離其鄰。鄰、行，古亦協。</p><h3 id="大過之漸" tabindex="-1">大過之漸 <a class="header-anchor" href="#大過之漸" aria-label="Permalink to “大過之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>台駘昧子，明知地理。障澤宣流，對居河涘。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>艮為台，坎為昧，《左傳昭元年》：&quot;昔金天氏有子曰昧，為玄冥，是生台駘，能業其官，宣汾洮，障大澤，帝用嘉之，封諸汾水&quot;，台駘昧子，言昧子台駘能治水障澤。宣，流也。坎為澤，艮止為障，坎為流、為河也。○流，汲古訛德，依宋元。居、涘，宋元本作君、作水，依汲古。</p><h3 id="大過之歸妹" tabindex="-1">大過之歸妹 <a class="header-anchor" href="#大過之歸妹" aria-label="Permalink to “大過之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>蓄水待時，以備火災。柱車絆馬，郊行出旅，可以無咎。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>通《漸》。坎水艮止，故曰蓄。艮為時、為待，故蓄水待時。互離為火，艮亦為火，故曰火災。震為車馬，坎陷故曰柱、曰絆。○待，宋元本作得，非，依汲古。</p><h3 id="大過之豐" tabindex="-1">大過之豐 <a class="header-anchor" href="#大過之豐" aria-label="Permalink to “大過之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>歲暮花落，君衰於德。榮寵隕墜，陰奪其室。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>互兌為秋，故曰歲暮。兌為華，巽隕落故曰花落。震為君、為榮寵，巽為隕墜。○第三句宋本作勞寵損墜，元本作勞寵損墮，今依汲古。奪，汲古作棄。茲依宋元本。</p><h3 id="大過之旅" tabindex="-1">大過之旅 <a class="header-anchor" href="#大過之旅" aria-label="Permalink to “大過之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>夏敗蔡悲，千里為市。黃落潱鬱，利得無有。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>未詳。敗、落，宋元本作販、作葉。</p><h3 id="大過之巽" tabindex="-1">大過之巽 <a class="header-anchor" href="#大過之巽" aria-label="Permalink to “大過之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>仲春巡狩，東見群後。昭德允明，不失其所。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>震為春、為巡狩，坎為仲，故曰仲春巡狩。震為東、為後，重震故曰群後。震為昭明。全用伏象。《虞書》：&quot;歲二月，東巡狩，至於貸宗，肆覲東後&quot;。</p><h3 id="大過之兌" tabindex="-1">大過之兌 <a class="header-anchor" href="#大過之兌" aria-label="Permalink to “大過之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>挒潔堁堁，締結難解。嫫母衒嫁，媒不得坐，自為身禍。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《晉》、《比》之《大有》。</p><h3 id="大過之渙" tabindex="-1">大過之渙 <a class="header-anchor" href="#大過之渙" aria-label="Permalink to “大過之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>鳥鳴庭中，以戒凶災。重門擊柝，備憂暴客。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥，震為鳴，艮為庭，故曰鳥鳴庭中。坎為災，《左傳襄三十年》：&quot;或叫於宋太廟曰嘻嘻出出，未幾果災&quot;。艮為門，正反艮故曰重門。震為鳴、為柝，艮手為擊。震為客，震躁而武故曰暴客。坎為憂。○鳴，汲古作嚕，庭作夜，茲依宋元本。</p><h3 id="大過之節" tabindex="-1">大過之節 <a class="header-anchor" href="#大過之節" aria-label="Permalink to “大過之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>朝霽暮露，瀐我衣襦，道無行牛。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>震為朝，坎為暮、為露，震為衣襦，瀐，濡也。艮為道、為牛，坎伏故無。○露，宋元本作霞，依汲古。瀐，汲古作纎，襦作濡，依宋元本。第三句依汲古，宋元本作退無得牛。</p><h3 id="大過之中孚" tabindex="-1">大過之中孚 <a class="header-anchor" href="#大過之中孚" aria-label="Permalink to “大過之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>抱璞懷玉，與桀相觸。詘坐不申，道無良人。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為玉，上艮為懷抱，兌剛滷，故曰桀，正反兌故曰相觸。艮為坐，巽伏故曰詘坐、曰不申。詘，屈也，折也。申，舒也。震為道、為人，艮為良，巽伏故曰無良人。○申，宋元本訛中，從汲古。</p><h3 id="大過之小過" tabindex="-1">大過之小過 <a class="header-anchor" href="#大過之小過" aria-label="Permalink to “大過之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>兩心相悅，共其茅藘。夙夜在公，不離房中，得君子意。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>巽為心，正反巽故曰兩心。兌為悅，正反兌故曰相悅。互巽為茅茹，故曰茅藘。艮手為共，故曰共其茅藘。按：《鄭風》：&quot;東門之壇，茹藘在阪&quot;，《傳》：&quot;茹藘，茅搜也，疏，蒨也，可染赤色&quot;，又雲&quot;出其東門，縞衣茹藘，聊可與娛&quot;，箋：茹藘，茅搜染巾也。聊可與娛者，且可留與我為樂，茲雲兩心相悅，正《詩》所謂聊可與娛也，雲共其茅藘，正箋所謂留與我為樂也。茹與茅義通，然林讀為茅藘，是齊詩與毛異讀也。夙，早也。震為旦，坎為夜，艮為房、為君子。○茅藘，宋本作柔筋，汲古作茀，依元本，藘與下意韻，又與首句意合，此明用東門詩意。劉毓崧以柔筋茀不合，雲宜作薇蕨，豈知薇蕨與相悅何涉，且與下意韻不協，而丁宴等仍採之。古書之難校若是。</p><h3 id="大過之既濟" tabindex="-1">大過之既濟 <a class="header-anchor" href="#大過之既濟" aria-label="Permalink to “大過之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>載饋如田，破鋤失餐。苗穢不闢，獨飢於年。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>○餐，依汲古，宋元本作食。穢，依宋元本，汲古作稼。</p><h3 id="大過之未濟" tabindex="-1">大過之未濟 <a class="header-anchor" href="#大過之未濟" aria-label="Permalink to “大過之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>甘露醴泉，太平機關。仁德咸應，歲樂民安。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>○咸，汲古作感，依宋元本。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
